Итог немного предсказуем: быстрый, но более сложный Perl проигрывает...
Возвращаясь к нашим баранам: SQLite::VecDB позволяет хранить базу векторов и метаданных в файле sqlite3, а также выполнять по ней поиск.
Вектора рассчитывает Ollama, и таким образом удалось наконец всё "переписать на Perl".
Упомянутый модуль для работы с Ollama по сути должен был всего лишь запросить вектор и подставить его куда нужно.
Как и говорил - оказалось быстрее написать свой вариант запроса:
#!/usr/bin/perl

use SQLite::VecDB;
use HTTP::Tiny;
use JSON;

my $dim = 768;
my $model = 'snowflake-arctic-embed2';
my $url = 'http://ollama:11434/api/embed';

my $vdb = SQLite::VecDB->new(
 db_file => '/data/vectors.db',
 dimensions => $dim,
);

my $coll = $vdb->collection('documents');

# сохранение в базу
sub add_vector {
 my ($id, $vector, $data, $content) = @_;

 $coll->add(
 id => $id,
 vector => $vector,
 metadata => $data,
 content => $content,
 );
}

my $http = HTTP::Tiny->new(timeout => 30);

# запрос вектора у Ollama
sub get_vector {
 my ($text) = @_;

 my $payload = {
 model => $model,
 input => $text,
 dimensions => $dim,
 };

 my $json = to_json($payload);

 my $response = $http->post(
 $url,
 {
 headers => { 'Content-Type' => 'application/json' },
 content => $json,
 }
 );

 if ($response->{success}) {
 my $data = from_json($response->{content});
 my $vector = $data->{embeddings}[0];
 return $vector;
 }
 else{
 print STDERR "Error: $response->{status} $response->{reason}\n$response->{content}\n";
 return undef;
 }

}

# поиск по вектору в базе
sub search_vector {
 my ($vector) = @_;

 my @results = $coll->search(
 vector => $vector,
 limit => 10,
 );

 my $ret = [];
 for my $r (@results) {
 my $t = {
 id => $r->{id},
 distance => $r->{distance},
 content => $r->{content},
 metadata => $r->{metadata},
 };
 push(@$ret, $t);
 }

 return $ret;
}

