В Perl, конечно же, есть готовые модули, в том числе достаточно серьезные фреймворки - но тут нужен простой, примитивный веб-сервис, для которого тащить что-то большое - всё равно что стрелять по воробьям из Царь-пушки.
Зато такое можно написать самому как нравится, это довольно просто:
#!/usr/bin/perl

package MicroHTTPD;

use strict;
use warnings;
use IO::Socket::INET;
use URI::Escape qw(uri_unescape);
use JSON;

# хардкод, но можно переназначить
our $port = 8080;
our $iface = '0.0.0.0';

our $routes = {
 'get' => {}, # сюда добавляем функции, вызываемые по GET
 'post' => {}, # сюда - вызываемые через POST
 'any' => {}, # сюда - те, которые можно и так и так.
};

# запуск сервера
sub serve {

 my $server = IO::Socket::INET->new(
 Local => $iface,
 LocalPort => $port,
 Listen => 10,
 Reuse => 1,
 ) or die "Startup error: $!\n";

 print "Server started: http://$iface:$port/\n";

 while (my $client = $server->accept()) {
 $client->autoflush(1);

 my $headers = '';
 while (my $line = <$client>) {
 $headers .= $line;
 last if $line eq "\r\n";
 }

 my ($request_line, @header_lines) = split /\r\n/, $headers;

 my ($method, $path, $http_version) =
 $request_line =~ /^(\S+)\s+(\S+)\s+(HTTP\/\d\.\d)$/;

 unless ($method && $path) {
 send_response($client, 400, "Bad Request", "Incorrect HTTP-request");
 close $client;
 next;
 }

 my %headers;

 for my $line (@header_lines) {
 next unless $line =~ /^([^:]+):\s*(.*)$/;
 $headers{lc $1} = $2;
 }

 my $body = '';

 if ($method eq 'POST') {
 my $content_length = $headers{'content-length'} || 0;

 if ($content_length > 1024 * 1024) {
 send_response($client, 413, "Payload Too Large", "Request body too large");
 close $client;
 next;
 }

 read($client, $body, $content_length);
 }

 if ($method eq 'GET') {
 my ($route, $query_string) = split /\?/, $path, 2;

 my %params = parse_params($query_string || '');

 my $processed = 0;
 for my $r (keys( %{ $routes->{get} } )){
 if ($route eq $r) {
 my ($ret_body, $ret_headers) = $routes->{get}->{ $r }->( \%params, \%headers );
 send_response($client, 200, "OK", $ret_body, $ret_headers);
 $processed = 1;
 last;
 }
 }
 for my $r (keys( %{ $routes->{any} } )){
 if ($route eq $r) {
 my ($ret_body, $ret_headers) = $routes->{any}->{ $r }->( \%params, \%headers );
 send_response($client, 200, "OK", $ret_body, $ret_headers);
 $processed = 1;
 last;
 }
 }
 if(!$processed){
 send_response($client, 404, "Not Found", "Method not found");
 }
 }
 elsif ($method eq 'POST') {
 my ($route) = split /\?/, $path, 2;

 my %params = ();
 if($headers{'content-type'} eq 'application/x-www-form-urlencoded'){
 %params = parse_params($body || '');
 }
 if($headers{'content-type'} eq 'application/json' ){
 my $t = from_json($body||'{}');
 %params = %$t;
 }

 my $processed = 0;
 for my $r (keys( %{ $routes->{post} } )){
 if ($route eq $r) {
 my ($ret_body, $ret_headers) = $routes->{post}->{ $r }->( \%params, \%headers );
 send_response($client, 200, "OK", $ret_body, $ret_headers);
 $processed = 1;
 last;
 }
 }
 for my $r (keys( %{ $routes->{any} } )){
 if ($route eq $r) {
 my ($ret_body, $ret_headers) = $routes->{any}->{ $r }->( \%params, \%headers );
 send_response($client, 200, "OK", $ret_body, $ret_headers);
 $processed = 1;
 last;
 }
 }
 if(!$processed){
 send_response($client, 404, "Not Found", "Method not found");
 }
 }
 else {
 send_response(
 $client,
 405,
 "Method Not Allowed",
 "Method Not Allowed",
 {
 'Content-Type' => "text/plain; charset=utf-8",
 'Allow' => "GET, POST",
 }
 );
 }

 close $client;
 }
}

sub parse_params {
 my ($data) = @_;

 my %params;

 for my $pair (split /&/, $data) {
 my ($key, $value) = split /=/, $pair, 2;

 $key = uri_unescape($key // '');
 $value = uri_unescape($value // '');

 $key =~ tr/+/ /;
 $value =~ tr/+/ /;

 $params{$key} = $value;
 }

 return %params;
}

sub send_response {
 my ($client, $status, $status_text, $body, $headers) = @_;

 $headers->{'Content-Type'} ||= 'text/plain; charset=utf-8';

 my $response =
 "HTTP/1.1 $status $status_text\r\n"
 . "Content-Length: " . length($body) . "\r\n";

 for my $x (keys(%$headers)){
 $response .= "$x:$headers->{$x}\r\n";
 }
 $response .=
 "Connection: close\r\n"
 . "\r\n"
 . $body;

 print $client $response;
}

1;
